7	import {
8	  BaseDeclarativeTool,
9	  Kind,
10	  type ToolInvocation,
11	  type ToolResult,
12	  BaseToolInvocation,
13	  type ToolCallConfirmationDetails,
14	  isTool,
15	} from '../tools/tools.js';
16	import type { AnsiOutput } from '../utils/terminalSerializer.js';
17	import type { Config } from '../config/config.js';
18	import type { MessageBus } from '../confirmation-bus/message-bus.js';
19	import type { AgentDefinition, AgentInputs } from './types.js';
20	import { SubagentToolWrapper } from './subagent-tool-wrapper.js';
21	import { SchemaValidator } from '../utils/schemaValidator.js';
22	import { formatUserHintsForModel } from '../utils/fastAckHelper.js';
23	
24	export class SubagentTool extends BaseDeclarativeTool<AgentInputs, ToolResult> {
25	  constructor(
26	    private readonly definition: AgentDefinition,
27	    private readonly config: Config,
28	    messageBus: MessageBus,
29	  ) {
30	    const inputSchema = definition.inputConfig.inputSchema;
31	
32	    // Validate schema on construction
33	    const schemaError = SchemaValidator.validateSchema(inputSchema);
34	    if (schemaError) {
35	      throw new Error(
36	        `Invalid schema for agent ${definition.name}: ${schemaError}`,
37	      );
38	    }
39	
40	    super(
41	      definition.name,
42	      definition.displayName ?? definition.name,
43	      definition.description,
44	      Kind.Think,
45	      inputSchema,
46	      messageBus,
47	      /* isOutputMarkdown */ true,
48	      /* canUpdateOutput */ true,
49	    );
50	  }
51	
52	  private _memoizedIsReadOnly: boolean | undefined;
53	
54	  override get isReadOnly(): boolean {
55	    if (this._memoizedIsReadOnly !== undefined) {
56	      return this._memoizedIsReadOnly;
57	    }
58	    // No try-catch here. If getToolRegistry() throws, we let it throw.
59	    // This is an invariant: you can't check read-only status if the system isn't initialized.
60	    this._memoizedIsReadOnly = SubagentTool.checkIsReadOnly(
61	      this.definition,
62	      this.config,
63	    );
64	    return this._memoizedIsReadOnly;
65	  }
66	
67	  private static checkIsReadOnly(
68	    definition: AgentDefinition,
69	    config: Config,
70	  ): boolean {
71	    if (definition.kind === 'remote') {
72	      return false;
73	    }
74	    const tools = definition.toolConfig?.tools ?? [];
75	    const registry = config.getToolRegistry();
76	
77	    if (!registry) {
78	      return false;
79	    }
80	
81	    for (const tool of tools) {
82	      if (typeof tool === 'string') {
83	        const resolvedTool = registry.getTool(tool);
84	        if (!resolvedTool || !resolvedTool.isReadOnly) {
85	          return false;
86	        }
87	      } else if (isTool(tool)) {
88	        if (!tool.isReadOnly) {
89	          return false;
90	        }
91	      } else {
92	        // FunctionDeclaration - we don't know, so assume NOT read-only
93	        return false;
94	      }
95	    }
96	    return true;
97	  }
98	
99	  protected createInvocation(
100	    params: AgentInputs,
101	    messageBus: MessageBus,
102	    _toolName?: string,
103	    _toolDisplayName?: string,
104	  ): ToolInvocation<AgentInputs, ToolResult> {
105	    return new SubAgentInvocation(
106	      params,
107	      this.definition,
108	      this.config,
109	      messageBus,
110	      _toolName,
111	      _toolDisplayName,
112	    );
113	  }
114	}
115	
116	class SubAgentInvocation extends BaseToolInvocation<AgentInputs, ToolResult> {
117	  private readonly startIndex: number;
118	
119	  constructor(
120	    params: AgentInputs,
121	    private readonly definition: AgentDefinition,
122	    private readonly config: Config,
123	    messageBus: MessageBus,
124	    _toolName?: string,
125	    _toolDisplayName?: string,
126	  ) {
127	    super(
128	      params,
129	      messageBus,
130	      _toolName ?? definition.name,
131	      _toolDisplayName ?? definition.displayName ?? definition.name,
132	    );
133	    this.startIndex = config.userHintService.getLatestHintIndex();
134	  }
135	
136	  getDescription(): string {
137	    return `Delegating to agent '${this.definition.name}'`;
138	  }
139	
140	  override async shouldConfirmExecute(
141	    abortSignal: AbortSignal,
142	  ): Promise<ToolCallConfirmationDetails | false> {
143	    const invocation = this.buildSubInvocation(
144	      this.definition,
145	      this.withUserHints(this.params),
146	    );
147	    return invocation.shouldConfirmExecute(abortSignal);
148	  }
149	
150	  async execute(
151	    signal: AbortSignal,
152	    updateOutput?: (output: string | AnsiOutput) => void,
153	  ): Promise<ToolResult> {
154	    const validationError = SchemaValidator.validate(
155	      this.definition.inputConfig.inputSchema,
156	      this.params,
157	    );
158	
159	    if (validationError) {
160	      throw new Error(
161	        `Invalid arguments for agent '${this.definition.name}': ${validationError}. Input schema: ${JSON.stringify(this.definition.inputConfig.inputSchema)}.`,
162	      );
163	    }
164	
165	    const invocation = this.buildSubInvocation(
166	      this.definition,
167	      this.withUserHints(this.params),
168	    );
169	
170	    return invocation.execute(signal, updateOutput);
171	  }
172	
173	  private withUserHints(agentArgs: AgentInputs): AgentInputs {
174	    if (this.definition.kind !== 'remote') {
175	      return agentArgs;
176	    }
177	
178	    const userHints = this.config.userHintService.getUserHintsAfter(
179	      this.startIndex,
180	    );
181	    const formattedHints = formatUserHintsForModel(userHints);
182	    if (!formattedHints) {
183	      return agentArgs;
184	    }
185	
186	    const query = agentArgs['query'];
187	    if (typeof query !== 'string' || query.trim().length === 0) {
188	      return agentArgs;
189	    }
190	
191	    return {
192	      ...agentArgs,
193	      query: `${formattedHints}\n\n${query}`,
194	    };
195	  }
196	
197	  private buildSubInvocation(
198	    definition: AgentDefinition,
199	    agentArgs: AgentInputs,
200	  ): ToolInvocation<AgentInputs, ToolResult> {
201	    const wrapper = new SubagentToolWrapper(
202	      definition,
203	      this.config,
204	      this.messageBus,
205	    );
206	
207	    return wrapper.build(agentArgs);
208	  }
209	}
