7	import type { Config } from '../config/config.js';
8	import { LocalAgentExecutor } from './local-executor.js';
9	import type { AnsiOutput } from '../utils/terminalSerializer.js';
10	import { BaseToolInvocation, type ToolResult } from '../tools/tools.js';
11	import { ToolErrorType } from '../tools/tool-error.js';
12	import type {
13	  LocalAgentDefinition,
14	  AgentInputs,
15	  SubagentActivityEvent,
16	} from './types.js';
17	import type { MessageBus } from '../confirmation-bus/message-bus.js';
18	
19	const INPUT_PREVIEW_MAX_LENGTH = 50;
20	const DESCRIPTION_MAX_LENGTH = 200;
21	
22	/**
23	 * Represents a validated, executable instance of a subagent tool.
24	 *
25	 * This class orchestrates the execution of a defined agent by:
26	 * 1. Initializing the {@link LocalAgentExecutor}.
27	 * 2. Running the agent's execution loop.
28	 * 3. Bridging the agent's streaming activity (e.g., thoughts) to the tool's
29	 * live output stream.
30	 * 4. Formatting the final result into a {@link ToolResult}.
31	 */
