import * as path from 'node:path';
import { Client } from '@modelcontextprotocol/sdk/client/index.js';
import { StdioClientTransport } from '@modelcontextprotocol/sdk/client/stdio.js';
import type { Config } from '../../config/config.js';
import { Storage } from '../../config/storage.js';

/**
 * The pinned version of the `chrome-devtools-mcp` package used to drive the
 * browser. Kept as a constant so the spawned command is deterministic.
 */
export const CHROME_DEVTOOLS_MCP_VERSION = '0.6.0';

/**
 * The identifier reported to the MCP server when this client connects.
 */
export const BROWSER_MCP_CLIENT_NAME = 'gemini-cli-browser-agent';

/**
 * The default profile directory used in persistent session mode. The path
 * intentionally ends in `cli-browser-profile`.
 */
const DEFAULT_BROWSER_PROFILE_DIR = path.join(
  Storage.getGlobalGeminiDir(),
  'cli-browser-profile',
);

/**
 * The timeout, in milliseconds, applied when connecting to the MCP server.
 */
const CONNECT_TIMEOUT_MS = 60_000;

/**
 * A single content item returned from an MCP tool call, normalized to the
 * subset of fields the browser agent cares about.
 */
export interface McpContentItem {
  type: 'text' | 'image';
  text?: string;
  data?: string;
  mimeType?: string;
}

/**
 * The normalized result of an MCP tool call.
 */
export interface McpToolCallResult {
  content?: McpContentItem[];
  isError?: boolean;
}

/**
 * A tool discovered from the MCP server.
 */
export interface McpTool {
  name: string;
  description?: string;
  inputSchema?: Record<string, unknown>;
}

/**
 * Manages the lifecycle of a browser via an isolated MCP client connected to
 * `chrome-devtools-mcp`.
 *
 * Unlike the general MCP tooling, this manager owns a dedicated raw MCP SDK
 * {@link Client} rather than routing through the shared
 * {@link McpClientManager}, so the browser agent's connection is fully
 * independent of user-configured MCP servers.
 */
export class BrowserManager {
  private client?: Client;
  private transport?: StdioClientTransport;
  private connected = false;

  constructor(private readonly config: Config) {}

  /**
   * Returns the raw MCP SDK client, constructing (and caching) it on first use.
   * Subsequent calls return the same instance without creating a new client.
   */
  async getRawMcpClient(): Promise<Client> {
    if (!this.client) {
      this.client = new Client(
        // The MCP SDK type additionally requires a `version`, but the browser
        // agent intentionally identifies itself with only a name.
        { name: BROWSER_MCP_CLIENT_NAME } as ConstructorParameters<
          typeof Client
        >[0],
      );
    }
    return this.client;
  }

  /**
   * Establishes the connection to the `chrome-devtools-mcp` server, spawning
   * Chrome according to the configured session mode.
   */
  async ensureConnection(): Promise<void> {
    if (this.connected) {
      return;
    }

    const { customConfig } = this.config.getBrowserAgentConfig();
    const sessionMode = customConfig.sessionMode ?? 'persistent';
    const headless = customConfig.headless ?? false;
    const profilePath = customConfig.profilePath;

    const args = [
      '-y',
      `chrome-devtools-mcp@${CHROME_DEVTOOLS_MCP_VERSION}`,
      '--experimental-vision',
    ];

    if (headless) {
      args.push('--headless');
    }

    if (sessionMode === 'isolated') {
      args.push('--isolated');
    } else if (sessionMode === 'existing') {
      args.push('--autoConnect');
    }

    if (profilePath) {
      args.push('--userDataDir', profilePath);
    } else if (sessionMode === 'persistent') {
      args.push('--userDataDir', DEFAULT_BROWSER_PROFILE_DIR);
    }

    const client = await this.getRawMcpClient();
    const transport = new StdioClientTransport({
      command: 'npx',
      args,
      stderr: 'pipe',
    });
    this.transport = transport;

    try {
      await client.connect(transport, { timeout: CONNECT_TIMEOUT_MS });
      this.connected = true;
    } catch (error) {
      try {
        await transport.close();
      } catch {
        // Best-effort cleanup; ignore secondary failures.
      }
      this.transport = undefined;
      throw this.buildConnectionError(error, sessionMode);
    }
  }

  /**
   * Builds a user-actionable error message for a failed connection attempt,
   * tailored to the configured session mode and the underlying failure.
   */
  private buildConnectionError(
    error: unknown,
    sessionMode: 'isolated' | 'persistent' | 'existing',
  ): Error {
    const originalMessage =
      error instanceof Error ? error.message : String(error);
    const lower = originalMessage.toLowerCase();

    if (sessionMode === 'existing') {
      return new Error(
        'Failed to connect to existing Chrome instance. Ensure Chrome is ' +
          'running with remote debugging enabled. You can inspect available ' +
          'targets at chrome://inspect/#remote-debugging, or launch Chrome ' +
          'with --remote-debugging-port=9222. ' +
          `Original error: ${originalMessage}`,
      );
    }

    const looksLikeAlreadyRunning =
      lower.includes('already running') ||
      lower.includes('already in use') ||
      lower.includes('in use') ||
      lower.includes('lock');

    if (looksLikeAlreadyRunning) {
      return new Error(
        'Chrome is already running with this profile. Close all Chrome ' +
          'windows using this profile and try again. Set sessionMode to ' +
          '"isolated" to launch a temporary, separate profile instead. ' +
          `Original error: ${originalMessage}`,
      );
    }

    const looksLikeTimeout =
      lower.includes('timed out') ||
      lower.includes('timeout') ||
      (error instanceof Error && error.name === 'TimeoutError');

    if (looksLikeTimeout) {
      return new Error(
        'Timed out launching Chrome. Chrome is not installed or could not be ' +
          'started. Install Google Chrome and try again. ' +
          `Original error: ${originalMessage}`,
      );
    }

    return new Error(
      `Failed to launch the browser (sessionMode: ${sessionMode}). ` +
        `Original error: ${originalMessage}`,
    );
  }

  /**
   * Returns the tools discovered from the connected MCP server.
   */
  async getDiscoveredTools(): Promise<McpTool[]> {
    const client = await this.getRawMcpClient();
    const response = await client.listTools();
    const tools = response.tools ?? [];
    return tools.map((tool) => ({
      name: tool.name,
      description: tool.description,
      inputSchema: tool.inputSchema as Record<string, unknown> | undefined,
    }));
  }

  /**
   * Calls a tool on the MCP server and normalizes the raw SDK response into an
   * {@link McpToolCallResult}.
   */
  async callTool(
    toolName: string,
    args: Record<string, unknown>,
    signal?: AbortSignal,
  ): Promise<McpToolCallResult> {
    const client = await this.getRawMcpClient();
    const raw = await client.callTool(
      { name: toolName, arguments: args },
      undefined,
      signal ? { signal } : undefined,
    );

    const rawContent = Array.isArray(
      (raw as { content?: unknown }).content,
    )
      ? // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
        ((raw as { content: unknown[] }).content as Array<
          Record<string, unknown>
        >)

