type ToolParams = Record<string, unknown>;

/**
 * The synthetic server name used for browser agent MCP tools. All browser
 * tools share this name for policy and confirmation purposes.
 */
export const BROWSER_MCP_SERVER_NAME = 'browser-agent';

/**
 * The name of the composite tool that is always added alongside the discovered
 * MCP tools.
 */
export const TYPE_TEXT_TOOL_NAME = 'type_text';

/**
 * Extracts and concatenates the textual content from an MCP tool result.
 */
function extractTextContent(content: McpContentItem[] | undefined): string {
  if (!content) {
    return '';
  }
  return content
    .filter((item) => item.type === 'text' && typeof item.text === 'string')
    .map((item) => item.text)
    .join('\n');
