        llmContent: `Error: ${textContent}`,
        returnDisplay: `Error: ${textContent}`,
        error: {
          message: textContent,
          type: ToolErrorType.MCP_TOOL_ERROR,
        },
      };
    }

    return {
      llmContent: textContent,
      returnDisplay: textContent,
      error: undefined,
