/**
 * The public name of the visual analysis tool.
 */
export const ANALYZE_SCREENSHOT_TOOL_NAME = 'analyze_screenshot';

type ToolParams = { instruction: string };

class AnalyzeScreenshotInvocation extends BaseToolInvocation<
  ToolParams,
  ToolResult
> {
  constructor(
    private readonly browserManager: BrowserManager,
    private readonly config: Config,
    params: ToolParams,
    messageBus: MessageBus,
  ) {
    super(params, messageBus, ANALYZE_SCREENSHOT_TOOL_NAME);
  }

  getDescription(): string {
    return `Analyze the current screenshot: ${this.params.instruction}`;
  }

  async execute(signal: AbortSignal): Promise<ToolResult> {
    // 1. Capture a screenshot of the current page.
    const screenshot = await this.browserManager.callTool(
      'take_screenshot',
      {},
      signal,
    );

    const image = screenshot.content?.find(
      (item) => item.type === 'image' && !!item.data,
    );

    if (!image || !image.data) {
      const message =
        'Failed to capture screenshot. The browser did not return any image ' +
        'content to analyze.';
      return {
        llmContent: message,
        returnDisplay: message,
        error: {
          message,
          type: ToolErrorType.EXECUTION_FAILED,
        },
      };
    }

    // 2. Send the screenshot and instruction to the configured visual model.
    const { customConfig } = this.config.getBrowserAgentConfig();
    const visualModel = customConfig.visualModel;

    try {
      const response = await this.config.getContentGenerator().generateContent(
        {
          model: visualModel ?? this.config.getModel(),
          contents: [
            {
              role: 'user',
              parts: [
                { text: this.params.instruction },
                {
                  inlineData: {
                    mimeType: image.mimeType ?? 'image/png',
                    data: image.data,
                  },
                },
              ],
            },
          ],
          config: {},
        },
        `browser-agent-analyze-screenshot-${randomUUID()}`,
        LlmRole.UTILITY_TOOL,
      );

      const parts = response.candidates?.[0]?.content?.parts;
      if (!parts || parts.length === 0) {
        const message =
          'Visual model returned no analysis. The response contained no ' +
          'content.';
        return {
          llmContent: message,
          returnDisplay: message,
          error: {
            message,
            type: ToolErrorType.EXECUTION_FAILED,
          },
        };
      }

      const analysis = getResponseText(response) ?? '';
      const content = `Visual Analysis Result:\n${analysis}`;
      return {
        llmContent: content,
        returnDisplay: content,
      };
    } catch (error) {
      const errorMsg = error instanceof Error ? error.message : String(error);

      if (/404|403|not found|permission/i.test(errorMsg)) {
        const message =
          `Visual analysis model is not available (model: ` +
          `${visualModel ?? 'unknown'}). ${errorMsg}`;
        return {
          llmContent: message,
          returnDisplay: message,
          error: {
            message,
            type: ToolErrorType.EXECUTION_FAILED,
          },
        };
      }

      const message = `Visual analysis failed: ${errorMsg}`;
      return {
        llmContent: message,
        returnDisplay: message,
        error: {
          message,
          type: ToolErrorType.EXECUTION_FAILED,
        },
      };
    }
  }
}

