const DESCRIPTION_MAX_LENGTH = 200;

/**
 * A tool invocation for the browser agent that handles the asynchronous setup
 * of the browser MCP connection and its cleanup once the agent finishes.
 */
export class BrowserAgentInvocation extends BaseToolInvocation<
  AgentInputs,
  ToolResult
> {
  constructor(
    private readonly config: Config,
    params: AgentInputs,
    messageBus: MessageBus,
    toolName?: string,
    toolDisplayName?: string,
  ) {
    super(
      params,
      messageBus,
      toolName ?? BROWSER_AGENT_NAME,
      toolDisplayName ?? BROWSER_AGENT_DISPLAY_NAME,
    );
  }

  getDescription(): string {
    const keys = Object.keys(this.params).join(', ');
    const description = `Delegating to the browser agent with inputs: { ${keys} }`;
    return description.slice(0, DESCRIPTION_MAX_LENGTH);
  }

  override toolLocations() {
    return [];
  }

  async execute(
    signal: AbortSignal,
    updateOutput?: (output: string | AnsiOutput) => void,
  ): Promise<ToolResult> {
    const printOutput = updateOutput
      ? (message: string) => updateOutput(message)
      : undefined;

    const { definition, browserManager } = await createBrowserAgentDefinition(
      this.config,
      this.messageBus,
      printOutput,
    );

    try {
      const invocation = new LocalSubagentInvocation(
        definition,
        this.config,
        this.params,
        this.messageBus,
        this._toolName,
        this._toolDisplayName,
      );
      return await invocation.execute(signal, updateOutput);
    } finally {
      await cleanupBrowserAgent(browserManager);
    }
  }
}
