  BROWSER_AGENT_NAME,
  buildBrowserSystemPrompt,
} from './browserAgentDefinition.js';

const BrowserAgentResultSchema = z.string();

/**
 * Creates the browser agent definition along with the {@link BrowserManager}
 * that owns the underlying MCP connection.
 *
 * This connects to the browser MCP server, wraps the discovered tools, and —
 * when a visual model is configured — additionally exposes the
 * `analyze_screenshot` tool and vision-specific guidance in the system prompt.
 *
 * @param config The runtime configuration.
 * @param messageBus The message bus used for tool policy/confirmation.
 * @param printOutput An optional callback for surfacing progress messages.
 * @returns The agent definition and the browser manager to be cleaned up later.
 */
export async function createBrowserAgentDefinition(
  config: Config,
  messageBus: MessageBus,
  printOutput?: (msg: string) => void,
): Promise<{
  definition: LocalAgentDefinition<typeof BrowserAgentResultSchema>;
  browserManager: BrowserManager;
}> {
  const browserManager = new BrowserManager(config);
  await browserManager.ensureConnection();

  printOutput?.('Browser agent connected to Chrome.');

  const tools = await createMcpDeclarativeTools(browserManager, messageBus);

  const browserConfig = config.getBrowserAgentConfig();
  const visualModel = browserConfig.customConfig.visualModel;
  const visionEnabled = !!visualModel;

  if (visionEnabled) {
    tools.push(
      createAnalyzeScreenshotTool(browserManager, config, messageBus),
    );
  }

  const definition: LocalAgentDefinition<typeof BrowserAgentResultSchema> = {
    name: BROWSER_AGENT_NAME,
    kind: 'local',
    displayName: BROWSER_AGENT_DISPLAY_NAME,
    description:
      'An experimental agent that autonomously controls a real web browser ' +
      'to accomplish web-based tasks such as navigation, form filling, and ' +
      'information gathering.',
    inputConfig: {
      inputSchema: {
        type: 'object',
        properties: {
          task: {
            type: 'string',
            description:
              'A detailed description of the web task to accomplish, ' +
              'including any starting URL and success criteria.',
          },
        },
        required: ['task'],
      },
    },
    outputConfig: {
      outputName: 'result',
      description:
        'A summary of the outcome of the browser task and any information ' +
        'gathered.',
      schema: BrowserAgentResultSchema,
    },
    modelConfig: {
      model: browserConfig.model ?? DEFAULT_GEMINI_MODEL,
      generateContentConfig: {
        temperature: 0.1,
        topP: 0.95,
      },
    },
    runConfig: {
      maxTimeMinutes: 10,
      maxTurns: 25,
    },
    toolConfig: {
      tools,
    },
    promptConfig: {
      systemPrompt: buildBrowserSystemPrompt(visionEnabled),
      query:
        'Accomplish the following web task:\n<task>\n${task}\n</task>',
    },
  };

  return { definition, browserManager };
}

/**
 * Cleans up the browser agent by closing the browser manager. Resolves to
 * undefined even if closing throws.
 */
export async function cleanupBrowserAgent(
  browserManager: BrowserManager,
): Promise<void> {
  try {
    await browserManager.close();
  } catch {
    // Swallow cleanup errors — closing is best-effort.
  }
}
