 * Manages the lifecycle of a browser via an isolated MCP client connected to
 * `chrome-devtools-mcp`.
 *
 * Unlike the general MCP tooling, this manager owns a dedicated raw MCP SDK
 * {@link Client} rather than routing through the shared
 * {@link McpClientManager}, so the browser agent's connection is fully
 * independent of user-configured MCP servers.
 */
export class BrowserManager {
  private client?: Client;
  private connected = false;

  constructor(private readonly config: Config) {}

  /**
   * Returns the raw MCP SDK client, constructing (and caching) it on first use.
   * Subsequent calls return the same instance without creating a new client.
   */
  async getRawMcpClient(): Promise<Client> {
    if (!this.client) {
      // The MCP SDK type additionally requires a `version`, but the browser
      // agent intentionally identifies itself with only a name.
      // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
      const clientInfo = { name: BROWSER_MCP_CLIENT_NAME } as ConstructorParameters<
        typeof Client
      >[0];
      this.client = new Client(clientInfo);
    }
    return this.client;
  }

  /**
   * Establishes the connection to the `chrome-devtools-mcp` server, spawning
   * Chrome according to the configured session mode.
   */
  async ensureConnection(): Promise<void> {
    if (this.connected) {
      return;
    }

    const { customConfig } = this.config.getBrowserAgentConfig();
    const sessionMode = customConfig.sessionMode ?? 'persistent';
    const headless = customConfig.headless ?? false;
    const profilePath = customConfig.profilePath;

